INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'الحدث اللي هيحجز جزء من رصيد البنك في الفصل الجاي:', '["خطاب الضمان الابتدائي لمناقصة برج زهرة النرجس","شراء معدات جديدة","توزيع أرباح على الشريكين","سداد ضريبة الدخل"]', 0, 'الفصل التاني: كراسة شروط وخطاب ضمان ابتدائي هيحجز جزء من الـ 4,131,400 (الوحدة 1.4).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'الحدث اللي هيحجز جزء من رصيد البنك في الفصل الجاي:');
