-- كورس محاسبة المقاولات: المقدمة، المستويات السبعة، الامتحانات، وأسئلة المستوى الأول (اتولد من scripts/build_contracting.py)
UPDATE courses SET subtitle = 'من رأس المال لحد تسليم المفتاح، مع قصة شركة الوعد للمقاولات', intro = 'عاصم مهندس مدني شبع شغل عند الناس، وعماد محاسب قانوني عارف مصايد السوق شبر شبر. اتفقوا على قهوة في مدينة نصر يفتحوا "شركة الوعد للمقاولات" برأس مال 10 مليون جنيه. في الكورس ده هتمشي معاهم من أول جنيه دخل البنك، لمناقصة برج "زهرة النرجس" في التجمع الخامس، لخطابات الضمان والدفعة المقدمة، لحديد الموقع ومستخلصات مقاولي الباطن، لحد التسليم النهائي والميزانية الختامية. كل الأرقام متصلة من أول مستوى لآخر مستوى، وكل مطب في الموقع ليه قيد ومستند ومعيار، على أحدث قوانين الضرايب في مصر.', audience = 'المحاسبين حديثي التخرج والـ Junior، ومحاسبي المواقع، وأي حد عايز يشتغل في شركات المقاولات' WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'البداية وتأسيس الكيان', 'تأسيس الشركة وجاري الشركاء، مصاريف التأسيس (معيار 23)، تكلفة الأصول الثابتة وسياسة الإهلاك (معيار 10)، وضريبة القيمة المضافة على المعدات بعد القانون 157 لسنة 2025.', 'عاصم عايز ينزل يشتري معدات ويدخل مناقصات بكرة الصبح، وعماد بيقوله: "الـ 10 مليون دول يتبخروا في ست شهور". هنعرف إيه اللي يتحط أصل وإيه اللي يتحمل مصروف، وليه الـ 14% اللي على فاتورة اللودر مش تكلفة.' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'كراسة الشروط ودخول المناقصات', 'مناقصة برج زهرة النرجس، معالجة تكلفة الكراسة طبقاً لمعيار 48، خطاب الضمان الابتدائي والغطاء النقدي المقيد، والحسابات النظامية خارج الميزانية.', 'إعلان في الجريدة عن برج بـ 50 مليون في التجمع الخامس. الكراسة بفلوس، والبنك عايز يحجز جزء من الرصيد قبل ما يطلع خطاب الضمان. يا ترى الفلوس المحجوزة دي لسه بتاعتنا؟' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'الفوز بالمشروع والبدء الفعلي', 'الترسية بـ 48 مليون، خطاب ضمان حسن التنفيذ، الدفعة المقدمة 10% كالتزام مش إيراد، وفتح مركز التكلفة 101 وأكواده الثلاثية (المشروع، المرحلة، بند المقايسة).', 'الشركة كسبت المناقصة، وشيك الدفعة المقدمة دخل البنك. عاصم فاكر إن الشركة بقت غنية، وعماد بيقوله إن الفلوس دي دين علينا لحد ما نشتغلها.' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'المعركة في الموقع', 'مخزون وتشوينات الموقع وأذون الإضافة والصرف، الأجور ومصاريف الموقع، مستخلص مقاول الباطن واستقطاعاته (ضمان أعمال، خصم 1% نموذج 41، تأمينات)، وضريبة القيمة المضافة على مشتريات الموقع ومقاولي الباطن.', 'الحديد وصل والأسمنت اتشوّن، والمعلم حامد داخل المكتب عايز مستخلصه كامل. هنعرف إزاي الخامة ماتبقاش تكلفة إلا بإذن صرف، وإزاي نفك استقطاعات مستخلص الباطن جنيه جنيه.' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'المستخلصات والإيرادات', 'المستخلص الجاري الأول، الاعتراف بالإيراد على مدار الوقت (معيار 48)، ضريبة القيمة المضافة 14% وخصم المدخلات، استرداد الدفعة المقدمة، احتجاز ضمان الأعمال، والخصم تحت حساب الضريبة.', 'الاستشاري اعتمد أول مستخلص. بس الشيك اللي وصل أقل بكتير من قيمة الأعمال. هنعرف كل جنيه اتخصم راح فين، وإمتى الشركة تعترف بالإيراد.' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'الحسابات الختامية وتسليم المفتاح', 'إنجاز 100%، التسليم الابتدائي واسترداد ضمان الأعمال، التسليم النهائي وفك الضمانات، الإهلاك كتكلفة مشروع، ضريبة الدخل 22.5%، وإعداد قائمة الدخل والمركز المالي.', 'البرج اتسلم والضمانات اتفكت. اللحظة اللي عاصم وعماد مستنينها: الشركة كسبت كام بجد بعد الإهلاك والضرايب؟ وكل شريك نصيبه كام؟' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50, 15 FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'خريطة السيطرة والمطبات الواقعية', 'فروق الأسعار طبقاً لقانون التعاقدات الحكومية 182 لسنة 2018، الأجور الحكمية في قانون التأمينات 148 لسنة 2019، غرامات التأخير ودفتر أحوال الموقع، شجرة حسابات المقاولات، ومصفوفة مراكز التكلفة.', 'المشروع خلص بسلام، بس عماد قاعد على القهوة بيحكي عن الشركات اللي وقعت: حديد غلي في نص المشروع، تأمينات اتحسبت بأثر رجعي، وغرامة تأخير أكلت الربح كله. هنا هتمسك الأدوات اللي بتحمي المقاول من الإفلاس.' FROM courses WHERE slug = 'contracting';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50, 15 FROM courses WHERE slug = 'contracting';
