INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 7, 'الامتحان الشامل (المستويات 1 إلى 7)', 20, 50, 40 FROM courses WHERE slug = 'contracting';
